<?php require_once 'inc/auth.php';require_once '../config/koneksi.php';$title='Pesanan Pelanggan';$rows=$conn->query("SELECT p.*,pr.nama_produk FROM pesanan p LEFT JOIN produk pr ON pr.id=p.produk_id ORDER BY p.id DESC");if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$status=$_POST['status']??'Menunggu';$allowed=['Menunggu','Diproses','Selesai','Dibatalkan'];if(in_array($status,$allowed,true)){ $s=$conn->prepare('UPDATE pesanan SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute(); } header('Location: pesanan.php');exit;}include 'inc/header.php';?><div class="page-title"><div><p class="eyebrow-admin">ORDER MANAGEMENT</p><h1>Pesanan Pelanggan</h1><p>Kelola status pesanan yang masuk dari website.</p></div></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Pelanggan</th><th>Produk</th><th>Jumlah</th><th>Kontak</th><th>Alamat</th><th>Status</th><th>Tanggal</th></tr><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><b><?=htmlspecialchars($r['nama_pelanggan'])?></b><br><small><?=htmlspecialchars($r['email'])?></small></td><td><?=htmlspecialchars($r['nama_produk']??'-')?></td><td><?=$r['jumlah']?></td><td><?=htmlspecialchars($r['no_hp'])?></td><td><?=htmlspecialchars($r['alamat'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option <?=$r['status']==='Menunggu'?'selected':''?>>Menunggu</option><option <?=$r['status']==='Diproses'?'selected':''?>>Diproses</option><option <?=$r['status']==='Selesai'?'selected':''?>>Selesai</option><option <?=$r['status']==='Dibatalkan'?'selected':''?>>Dibatalkan</option></select></form></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endwhile;else:?><tr><td colspan="8" class="empty">Belum ada pesanan.</td></tr><?php endif;?></table></div><?php include 'inc/footer.php';?>
